package com.ke.ticketsystemke.service;
import com.ke.ticketsystemke.dto.*; import com.ke.ticketsystemke.entity.*; import com.ke.ticketsystemke.repository.*;
import org.springframework.http.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.server.ResponseStatusException; import java.time.*; import java.util.*;
@Service
public class WarrantyResolutionService {
 public static final String MOVE_READY="WARRANTY_MOVE_TO_READY_DELIVERY", CONTINUE_PAID="WARRANTY_CONTINUE_AS_PAID_REPAIR"; private static final ZoneId ZONE=ZoneId.of("Asia/Kolkata");
 private final TicketRepository tickets; private final WarrantyClaimRepository claims; private final AccessService access; private final WarrantyClaimEventService audit; private final WarrantyClaimService claimService; private final GenericTransitionExecutorService transitionValidator; private final WorkflowTransitionExecutionService transitionExecutor;
 public WarrantyResolutionService(TicketRepository tickets,WarrantyClaimRepository claims,AccessService access,WarrantyClaimEventService audit,WarrantyClaimService claimService,GenericTransitionExecutorService transitionValidator,WorkflowTransitionExecutionService transitionExecutor){this.tickets=tickets;this.claims=claims;this.access=access;this.audit=audit;this.claimService=claimService;this.transitionValidator=transitionValidator;this.transitionExecutor=transitionExecutor;}
 @Transactional public WarrantyResolutionResponse manufacturerRepairDone(Long ticketId,Long claimId,ManufacturerRepairDoneRequest r,String actor){Context x=context(ticketId,claimId,r.version(),actor,true);WarrantyClaim c=x.claim();requirePending(c);requireComplaintOrOverride(c,r.managerOverrideReason());if(c.getState()!=WarrantyClaimState.VISIT_COMPLETED_AWAITING_RESULT&&trim(r.managerOverrideReason())==null)bad("A completed manufacturer visit or manager override reason is required");notFuture(r.completionDate(),"Completion date");c.setResult(WarrantyClaimResult.MANUFACTURER_REPAIR_DONE);c.setState(WarrantyClaimState.MANUFACTURER_REPAIR_COMPLETED);c.setManufacturerRepairCompletedAt(Instant.now());c.setManufacturerRepairCompletionDate(r.completionDate());c.setManufacturerRepairCompletionNotes(trim(r.completionNotes()));c.setManufacturerRepairReference(trim(r.manufacturerReference()));if(trim(r.engineerName())!=null)c.setManufacturerEngineerName(trim(r.engineerName()));if(trim(r.serviceCenterName())!=null)c.setManufacturerServiceCenterName(trim(r.serviceCenterName()));stopFollowUp(c);save(c,actor);String summary="Manufacturer warranty repair completed";audit.record(c,WarrantyClaimEventType.WARRANTY_MANUFACTURER_REPAIR_COMPLETED,actor,summary,Map.of("completionDate",r.completionDate(),"manufacturerReference",safe(c.getManufacturerRepairReference()),"managerOverrideReason",safe(r.managerOverrideReason())));return response(c,x.ticket(),null,summary);}
 @Transactional public WarrantyResolutionResponse moveToReadyDelivery(Long ticketId,Long claimId,WarrantyVersionRequest r,String actor){Context x=context(ticketId,claimId,r.version(),actor,true);WarrantyClaim c=x.claim();if(c.getResult()!=WarrantyClaimResult.MANUFACTURER_REPAIR_DONE||c.getState()!=WarrantyClaimState.MANUFACTURER_REPAIR_COMPLETED)conflict("Warranty repair is not ready for delivery workflow");TicketResponse ticketResult=executeConfigured(x.ticket(),MOVE_READY,actor,"Warranty manufacturer repair completed");c.setState(WarrantyClaimState.DELIVERY_PENDING);save(c,actor);String summary="Warranty ticket moved toward ready delivery";audit.record(c,WarrantyClaimEventType.WARRANTY_MOVED_TO_READY_DELIVERY,actor,summary,workflowMeta(MOVE_READY,x.ticket(),ticketResult));return response(c,x.ticket(),ticketResult,summary);}
 @Transactional public WarrantyResolutionResponse reject(Long ticketId,Long claimId,RejectWarrantyRequest r,String actor){Context x=context(ticketId,claimId,r.version(),actor,true);WarrantyClaim c=x.claim();requirePending(c);requireComplaintOrOverride(c,r.managerOverrideReason());notFuture(r.rejectionDate(),"Rejection date");c.setResult(WarrantyClaimResult.WARRANTY_REJECTED);c.setWarrantyRejectedAt(Instant.now());c.setWarrantyRejectionDate(r.rejectionDate());c.setWarrantyRejectionReason(trim(r.rejectionReason()));c.setRejectionDecision(r.decision());stopFollowUp(c);TicketResponse ticketResult=null;WarrantyClaimEventType event=WarrantyClaimEventType.WARRANTY_REJECTED;String summary="Warranty rejected";if(r.decision()==WarrantyRejectionDecision.CONTINUE_AS_PAID_REPAIR){ticketResult=executeConfigured(x.ticket(),CONTINUE_PAID,actor,"Warranty rejected; continue as paid repair");close(c,actor);event=WarrantyClaimEventType.WARRANTY_CONTINUED_AS_PAID_REPAIR;summary="Warranty rejected; continued as paid repair";}else if(r.decision()==WarrantyRejectionDecision.CLOSE_WARRANTY_CLAIM){close(c,actor);summary="Warranty rejected and claim closed";}else c.setState(WarrantyClaimState.WARRANTY_REJECTED_AWAITING_DECISION);save(c,actor);Map<String,Object> meta=new LinkedHashMap<>();meta.put("rejectionDate",r.rejectionDate());meta.put("decision",r.decision());meta.put("workflowAction",ticketResult==null?"":CONTINUE_PAID);audit.record(c,event,actor,summary,meta);return response(c,x.ticket(),ticketResult,summary);}
 @Transactional public WarrantyResolutionResponse customerDecision(Long ticketId,Long claimId,RecordWarrantyCustomerDecisionRequest r,String actor){Context x=context(ticketId,claimId,r.version(),actor,true);WarrantyClaim c=x.claim();if(c.getResult()!=WarrantyClaimResult.WARRANTY_REJECTED||c.getRejectionDecision()!=WarrantyRejectionDecision.AWAIT_CUSTOMER_DECISION)conflict("Warranty claim is not awaiting a customer decision");if(r.decision()!=WarrantyRejectionDecision.CONTINUE_AS_PAID_REPAIR&&r.decision()!=WarrantyRejectionDecision.CLOSE_WARRANTY_CLAIM)bad("Customer decision must continue as paid repair or close the warranty claim");notFuture(r.decisionDate(),"Decision date");c.setCustomerDecisionAt(Instant.now());c.setCustomerDecisionDate(r.decisionDate());c.setCustomerDecisionNotes(trim(r.decisionNotes()));c.setRejectionDecision(r.decision());TicketResponse ticketResult=null;String summary="Warranty rejection decision recorded";WarrantyClaimEventType event=WarrantyClaimEventType.WARRANTY_REJECTION_DECISION_RECORDED;if(r.decision()==WarrantyRejectionDecision.CONTINUE_AS_PAID_REPAIR){ticketResult=executeConfigured(x.ticket(),CONTINUE_PAID,actor,"Customer chose paid repair after warranty rejection");event=WarrantyClaimEventType.WARRANTY_CONTINUED_AS_PAID_REPAIR;summary="Customer continued as paid repair";}close(c,actor);save(c,actor);audit.record(c,event,actor,summary,Map.of("decisionDate",r.decisionDate(),"decision",r.decision(),"workflowAction",ticketResult==null?"":CONTINUE_PAID));return response(c,x.ticket(),ticketResult,summary);}
 @Transactional public WarrantyResolutionResponse customerDidNotProceed(Long ticketId,Long claimId,CustomerDidNotProceedRequest r,String actor){Context x=context(ticketId,claimId,r.version(),actor,true);WarrantyClaim c=x.claim();requirePending(c);notFuture(r.decisionDate(),"Decision date");c.setResult(WarrantyClaimResult.CUSTOMER_DID_NOT_PROCEED);c.setCustomerDidNotProceedAt(Instant.now());c.setCustomerDidNotProceedDate(r.decisionDate());c.setCustomerDidNotProceedReason(trim(r.reason()));c.setCustomerJourneyDecision(r.ticketJourneyDecision());stopFollowUp(c);TicketResponse ticketResult=null;if(r.ticketJourneyDecision()==WarrantyCustomerJourneyDecision.CONTINUE_AS_PAID_REPAIR){ticketResult=executeConfigured(x.ticket(),CONTINUE_PAID,actor,"Customer did not continue warranty; paid repair selected");close(c,actor);}else if(r.ticketJourneyDecision()==WarrantyCustomerJourneyDecision.CLOSE_WARRANTY_CLAIM)close(c,actor);else c.setState(WarrantyClaimState.CUSTOMER_DECISION_PENDING);save(c,actor);String summary="Customer did not proceed with warranty";audit.record(c,WarrantyClaimEventType.WARRANTY_CUSTOMER_DID_NOT_PROCEED,actor,summary,Map.of("decisionDate",r.decisionDate(),"ticketJourneyDecision",r.ticketJourneyDecision(),"workflowAction",ticketResult==null?"":CONTINUE_PAID));return response(c,x.ticket(),ticketResult,summary);}
 @Transactional public WarrantyResolutionResponse replacementApproved(Long ticketId,Long claimId,ReplacementApprovedRequest r,String actor){Context x=context(ticketId,claimId,r.version(),actor,true);WarrantyClaim c=x.claim();requirePending(c);requireComplaintOrOverride(c,null);if(trim(r.approvalReference())==null&&trim(r.approvalNotes())==null)bad("Approval reference or notes are required");notFuture(r.approvalDate(),"Approval date");c.setReplacementApprovedAt(Instant.now());c.setReplacementApprovalDate(r.approvalDate());c.setReplacementApprovalReference(trim(r.approvalReference()));c.setExpectedReplacementDate(r.expectedReplacementDate());c.setReplacementApprovalNotes(trim(r.approvalNotes()));c.setState(WarrantyClaimState.REPLACEMENT_APPROVED_AWAITING_PRODUCT);stopFollowUp(c);save(c,actor);String summary="Manufacturer replacement approved; awaiting product";audit.record(c,WarrantyClaimEventType.WARRANTY_REPLACEMENT_APPROVED,actor,summary,Map.of("approvalDate",r.approvalDate(),"approvalReference",safe(r.approvalReference()),"expectedReplacementDate",safe(r.expectedReplacementDate())));return response(c,x.ticket(),null,summary);}
 @Transactional public WarrantyResolutionResponse closeClaim(Long ticketId,Long claimId,CloseWarrantyClaimRequest r,String actor){Context x=context(ticketId,claimId,r.version(),actor,true);WarrantyClaim c=x.claim();if(c.getResult()==WarrantyClaimResult.PENDING)conflict("A pending warranty result cannot be closed through this action");close(c,actor);save(c,actor);String summary="Warranty claim closed";audit.record(c,WarrantyClaimEventType.WARRANTY_CLAIM_CLOSED,actor,summary,Map.of("notes",r.notes()));return response(c,x.ticket(),null,summary);}
 private TicketResponse executeConfigured(Ticket ticket,String key,String actor,String reason){try{var plan=transitionValidator.prepareActionExecution(ticket.getId(),key,actor);GenericTransitionExecutionRequest request=new GenericTransitionExecutionRequest();request.setReason(reason);return transitionExecutor.execute(plan,actor,request);}catch(ResponseStatusException ex){if(ex.getStatusCode()==HttpStatus.FORBIDDEN)throw ex;if(ex.getStatusCode()==HttpStatus.CONFLICT)throw new ResponseStatusException(HttpStatus.CONFLICT,"Warranty workflow action configuration is ambiguous");throw new ResponseStatusException(HttpStatus.CONFLICT,"This warranty action is not configured for the ticket's current workflow");}}
 private Context context(Long ticketId,Long claimId,Long version,String actor,boolean resolve){access.requireAllowed(actor,AccessKey.VIEW_TICKETS);access.requireAllowed(actor,resolve?AccessKey.RESOLVE_WARRANTY:AccessKey.MANAGE_WARRANTY);Ticket t=tickets.findById(ticketId).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Ticket not found"));WarrantyClaim c=claims.findById(claimId).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Warranty claim not found"));if(!c.getTicket().getId().equals(ticketId))throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Warranty claim not found");if(!c.isActive()||c.getState()==WarrantyClaimState.CLOSED)conflict("Warranty claim is not editable");if(!Objects.equals(c.getVersion(),version))conflict("Warranty claim was updated by another user");return new Context(t,c);}
 private void requirePending(WarrantyClaim c){if(c.getResult()!=WarrantyClaimResult.PENDING)conflict("Warranty result is already recorded");}private void requireComplaintOrOverride(WarrantyClaim c,String override){if((c.getManufacturerComplaintNumber()==null||c.getComplaintRegisteredDate()==null)&&trim(override)==null)bad("Registered complaint or manager override reason is required");}
 private void close(WarrantyClaim c,String actor){c.setActive(false);c.setState(WarrantyClaimState.CLOSED);c.setResolvedAt(Instant.now());c.setClaimClosedAt(Instant.now());c.setClaimClosedByEmployeeId(actor);stopFollowUp(c);}private void stopFollowUp(WarrantyClaim c){c.setNextFollowUpDate(null);c.setFollowUpSource(null);}
 private void save(WarrantyClaim c,String actor){c.setUpdatedByEmployeeId(actor);claims.saveAndFlush(c);}private WarrantyResolutionResponse response(WarrantyClaim c,Ticket t,TicketResponse tr,String summary){return new WarrantyResolutionResponse(claimService.response(c,t),tr,summary);}private Map<String,Object> workflowMeta(String key,Ticket before,TicketResponse after){return Map.of("workflowAction",key,"ticketStatus",safe(after==null?null:after.statusKey()));}
 private void notFuture(LocalDate d,String label){if(d.isAfter(LocalDate.now(ZONE)))bad(label+" cannot be in the future");}private String trim(String v){return v==null||v.trim().isEmpty()?null:v.trim();}private Object safe(Object v){return v==null?"":v;}private void bad(String m){throw new ResponseStatusException(HttpStatus.BAD_REQUEST,m);}private void conflict(String m){throw new ResponseStatusException(HttpStatus.CONFLICT,m);}private record Context(Ticket ticket,WarrantyClaim claim){}
}
